import { Link } from "react-router-dom";

export default function Accueil() {
  return (
    <div style={{ textAlign: "center", padding: "60px 20px" }}>
      <h1 style={{ fontSize: "42px", color: "#e44d26" }}>Bienvenue sur MonShop 🛍️</h1>
      <p style={{ fontSize: "18px", color: "#666", margin: "20px 0" }}>Découvrez nos produits au meilleur prix</p>
      <Link to="/catalogue">
        <button style={{ backgroundColor: "#e44d26", color: "white", padding: "14px 30px", border: "none", borderRadius: "8px", fontSize: "16px", cursor: "pointer" }}>
          Voir le catalogue →
        </button>
      </Link>
    </div>
  );
}
